#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int longestAwesome(std::string s) {
        std::vector<int> seen(1024, -2);
        seen[0] = -1;
        int mask = 0, ans = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            mask ^= (1 << (s[i] - '0'));
            if (seen[mask] != -2) ans = std::max(ans, i - seen[mask]);
            for (int d = 0; d < 10; ++d) {
                int target = mask ^ (1 << d);
                if (seen[target] != -2) ans = std::max(ans, i - seen[target]);
            }
            if (seen[mask] == -2) seen[mask] = i;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int longestAwesome(String s) {
        int[] seen = new int[1024];
        Arrays.fill(seen, -2);
        seen[0] = -1;
        int mask = 0, ans = 0;
        for (int i = 0; i < s.length(); i++) {
            mask ^= (1 << (s.charAt(i) - '0'));
            if (seen[mask] != -2) ans = Math.max(ans, i - seen[mask]);
            for (int d = 0; d < 10; d++) {
                int target = mask ^ (1 << d);
                if (seen[target] != -2) ans = Math.max(ans, i - seen[target]);
            }
            if (seen[mask] == -2) seen[mask] = i;
        }
        return ans;
    }
}

var longestAwesome = function(s) {
    const seen = new Array(1024).fill(-2);
    seen[0] = -1;
    let mask = 0, ans = 0;
    for (let i = 0; i < s.length; i++) {
        mask ^= (1 << (s.charCodeAt(i) - 48));
        if (seen[mask] !== -2) ans = Math.max(ans, i - seen[mask]);
        for (let d = 0; d < 10; d++) {
            const target = mask ^ (1 << d);
            if (seen[target] !== -2) ans = Math.max(ans, i - seen[target]);
        }
        if (seen[mask] === -2) seen[mask] = i;
    }
    return ans;
};
